CREATE OR REPLACE FUNCTION public.decrement_product_stock_from_order_item() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE current_stock integer; BEGIN IF NEW.product_id IS NULL THEN RETURN NEW; END IF; IF NEW.qty IS NULL OR NEW.qty <= 0 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; SELECT stock_qty INTO current_stock FROM public.products WHERE id = NEW.product_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Product not found for order item'; END IF; IF current_stock < NEW.qty THEN RAISE EXCEPTION 'Insufficient stock for part %', COALESCE(NEW.part_no, 'unknown'); END IF; UPDATE public.products SET stock_qty = current_stock - NEW.qty WHERE id = NEW.product_id; RETURN NEW; END; $$; DROP TRIGGER IF EXISTS trg_decrement_product_stock_from_order_item ON public.order_items; CREATE TRIGGER trg_decrement_product_stock_from_order_item BEFORE INSERT ON public.order_items FOR EACH ROW EXECUTE FUNCTION public.decrement_product_stock_from_order_item();